<?php
namespace Nakhostin\PerformanceEngine\Optimization;
final class OptimizationInvalidationSubscriber { private $storage; public function __construct( OptimizationManifestStorage $storage ) { $this->storage = $storage; } public function register(): void { foreach ( array( 'switch_theme', 'upgrader_process_complete', 'activated_plugin', 'deactivated_plugin', 'npe/cache/purged', 'update_option_npe_settings', 'elementor/document/after_save', 'update_option_woodmart_options' ) as $hook ) { add_action( $hook, array( $this, 'flush' ) ); } add_action( 'save_post', array( $this, 'invalidate_post' ) ); add_action( 'woocommerce_update_product', array( $this, 'invalidate_post' ) ); } public function flush(): void { $this->storage->flush(); } public function invalidate_post( int $post_id ): void { $url = get_permalink( $post_id ); if ( is_string( $url ) ) { $this->storage->invalidate_url( $url ); } } }
